#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N;
    cin >> M >> N;

    vector<vector<int>> estoque(M, vector<int>(N));
    for (int i = 0; i < M; ++i)
        for (int j = 0; j < N; ++j)
            cin >> estoque[i][j];

    int P, total = 0;
    cin >> P;

    while (P--) {
        int I, J;
        cin >> I >> J;
        --I;
        --J;

        if (estoque[I][J] > 0) {
